-- Updates the booktabib Sample Clinic from 0020: the Arabic name now says نموذج, it gets a realistic
-- address and phone number, the booktabib dot logo as its main photo and a gallery of five pictures,
-- and it keeps two doctors (the sample dentist is removed). It stays hidden. Runs once like any
-- migration, and does nothing if an administrator has already deleted the clinic.
INSERT INTO "images" ("id","content_type","data") SELECT 'SAMPLEBANNER0001','image/webp','' WHERE EXISTS (SELECT 1 FROM "clinics" WHERE "id" = 'booktabib-sample-clinic') ON CONFLICT DO NOTHING;--> statement-breakpoint
