  "address" = '{"en": "Building 14, 60 Meter Street, Erbil", "ar": "مبنى 14، شارع 60 متري، أربيل", "ckb": "باڵەخانەی ١٤، شەقامی ٦٠ مەتری، هەولێر"}'::jsonb,
  "phone" = '07501234567',
  "about" = '{"en": "A sample clinic that shows how booktabib works: browse the doctors, request an appointment and follow your place in line live. Real clinics are joining soon.", "ar": "نموذج لعيادة يُظهر كيف يعمل booktabib: تصفّح الأطباء، اطلب موعدًا، وتابع دورك في الطابور مباشرة. العيادات الحقيقية تنضم قريبًا.", "ckb": "کلینیکێکی نموونەییە بۆ پیشاندانی چۆنیەتی کارکردنی booktabib: پزیشکەکان ببینە، داوای نۆرە بکە و ڕاستەوخۆ شوێنی خۆت لە ڕیزدا ببینە. کلینیکە ڕاستەقینەکان بەم زووانە دێن."}'::jsonb,
  "hours" = '{"en": "Saturday – Thursday: 9:00 AM – 5:00 PM\nFriday: closed", "ar": "السبت – الخميس: ٩:٠٠ ص – ٥:٠٠ م\nالجمعة: مغلق", "ckb": "شەممە – پێنجشەممە: ٩:٠٠ی بەیانی – ٥:٠٠ی ئێوارە\nهەینی: داخراوە"}'::jsonb,
  "info" = '[{"title": {"en": "This is a sample clinic", "ar": "هذه صفحة نموذج", "ckb": "ئەمە کلینیکێکی نموونەییە"}, "body": {"en": "This page shows how a clinic looks on booktabib: its doctors, prices, opening hours and photos.", "ar": "تُظهر هذه الصفحة شكل العيادة على booktabib: أطباؤها وأسعارها وأوقات الدوام والصور.", "ckb": "ئەم پەڕەیە شێوەی کلینیکێک لە booktabib پیشان دەدات: پزیشکەکان، نرخەکان، کاتی کارکردن و وێنەکان."}}, {"title": {"en": "Want your clinic here?", "ar": "هل تريد عيادتك هنا؟", "ckb": "دەتەوێت کلینیکەکەت لێرە بێت؟"}, "body": {"en": "Contact booktabib and your clinic can have a page like this one.", "ar": "تواصل مع booktabib لتحصل عيادتك على صفحة مثل هذه.", "ckb": "پەیوەندی بە booktabib بکە بۆ ئەوەی کلینیکەکەت پەڕەیەکی وەک ئەمەی هەبێت."}}]'::jsonb,
  "specialties" = '["family","pediatrics"]'::jsonb,
  "image_id" = 'SAMPLEBANNER0001',
  "gallery" = '["SAMPLEGALLERY001", "SAMPLEGALLERY002", "SAMPLEGALLERY003", "SAMPLEGALLERY004", "SAMPLEGALLERY005"]'::jsonb
WHERE "id" = 'booktabib-sample-clinic';--> statement-breakpoint
